87: function renderOverview(c,p,s) {
88:   const needs = [['Hunger',c.needs.hunger,'🥩'],['Energy',c.needs.energy,'☾'],['Hygiene',c.needs.hygiene,'✧'],['Enrichment',c.needs.fun,'♡']]
89:   return `<section class="panel-block"><div class="block-heading"><span>VITAL SIGNS</span><b class="stable"><i></i> STABLE</b></div>${needs.map(([n,v,icon])=>`<div class="need-row"><span class="need-icon">${icon}</span><span class="need-name">${n}</span><span class="need-track"><i style="width:${v}%;background:${v<28?'#ff7a72':v<55?'#ffc36a':'#77e6bf'}"></i></span><b>${Math.round(v)}%</b></div>`).join('')}</section>
