93: function renderGenome(c) {
94:   const groups = { frame:'FRAME', limb:'LIMBS', weapon:'ADAPTATIONS', adapt:'ANIMAL ADAPTATIONS', core:'CORE', form:'BODY PLAN', coat:'PIGMENT' }
95:   return `<div class="genome-summary"><small>DNA SEQUENCE<br><b>${dnaSequence(c.genome).slice(0,22)}…</b></small><span>GEN ${c.generation||0}</span></div>${Object.entries(groups).map(([group,label])=>`<section class="gene-group"><div class="gene-group-title">${label}<span>${GENES.filter(g=>g.group===group).length} LOCI</span></div>${GENES.filter(g=>g.group===group).map(g=>{const [a,b]=c.genome?.[g.key]||[0.5,0.5];return `<div class="gene-line" title="${esc(g.desc)}"><span>${g.label}</span><span class="alleles"><i style="width:${a*100}%"></i><i style="width:${b*100}%"></i></span><b>${Math.round((a+b)*50)}</b></div>`}).join('')}</section>`).join('')}`
96: }
97: function renderAbilities(c) {
98:   const moves = movesFor(c)
99:   return `<div class="ability-intro"><span>DNA-EXPRESSED ABILITIES</span><small>${moves.length} UNLOCKED</small></div>${moves.map(m=>`<article class="move-card"><div class="move-icon ${m.type}">${m.icon}</div><div class="move-info"><div><b>${esc(m.name)}</b><span>${m.tag}</span></div><p>${esc(m.desc)}</p><small>${m.type==='defend'?'RECOVERY':`POWER ${Math.round(m.power*34)}`} · COST ${Math.max(0,m.cost)} STA</small></div></article>`).join('')}<div class="ability-note">Abilities emerge from expressed traits. Breed for new combinations.</div>`
100: }
101: function care(action) {
102:   const c=selected()
103:   if(action==='feed') { if(game.food<1)return toast('You are out of nectar. Discover a creature to restock.'); if(c.needs.hunger>94)return toast(`${c.name} is already full.`); game.food--; c.needs.hunger=clamp(c.needs.hunger+38,0,100); c.needs.energy=clamp(c.needs.energy+5,0,100); toast(`${c.name} enjoyed a nectar fruit.`) }
104:   else if(action==='play') { if(c.needs.energy<12)return toast(`${c.name} is too tired to play. Let them rest.`); c.needs.fun=clamp(c.needs.fun+30,0,100); c.needs.energy=Math.max(0,c.needs.energy-8); toast(`${c.name} had a lovely play session.`) }
105:   else { c.needs.energy=clamp(c.needs.energy+36,0,100); c.needs.hygiene=clamp(c.needs.hygiene+8,0,100); toast(`${c.name} took a restorative nap.`) }
106:   persist(); renderProfile(); renderRoster()
107: }
108: function showModal(content) { $('#modal').innerHTML=content; $('#modal-layer').classList.remove('hidden') }
109: function closeModal() { $('#modal-layer').classList.add('hidden') }
110: function discover() {
111:   if(game.coins<60)return toast('You need 60 shards to discover a creature.')
112:   showModal(`<button class="modal-close" data-action="close" aria-label="Close discovery">×</button><div class="eyebrow">VERDANT HOLLOW · FIELD FIND</div><h2>Shape a new foundling</h2><p>Choose up to three adaptations to guarantee in this creature’s DNA. Every pick grows into a visible body part.</p><div class="adapt-grid">${ADAPTATIONS.map(a=>`<label class="adapt-option"><input type="checkbox" name="adaptation" value="${a.key}"><span class="adapt-icon">${a.icon}</span><span class="adapt-copy"><b>${a.name}</b><small>${a.source}</small><em>${a.note}</em></span><i class="adapt-check">＋</i></label>`).join('')}</div><div class="adapt-footer"><span id="adapt-count">0 / 3 SELECTED</span><small>DISCOVERY COST · 60 ✧</small></div><div class="modal-actions"><button class="secondary-btn" data-action="close">CANCEL</button><button class="primary-btn" data-action="discover-confirm">SEARCH THE HOLLOW ↗</button></div>`)
113: }
114: function discoverConfirm() {
115:   if(game.coins<60)return toast('You need 60 shards to discover a creature.')
116:   const selectedTraits=[...document.querySelectorAll('input[name="adaptation"]:checked')].map(input=>input.value).filter(key=>ADAPTATIONS.some(a=>a.key===key)).slice(0,3)
117:   game.coins-=60
