120:   c.needs=freshNeeds(82)
121:   game.creatures.push(c); game.selected=c.id; closeModal()
122:   if(mode==='habitat') { world.addCreature(c,{position:[(Math.random()-.5)*5,0,(Math.random()-.5)*5]}); world.setSelected(c.id) }
123:   persist(); renderRoster(); renderProfile(); toast(`${c.name} joined your sanctuary with ${selectedTraits.length} adaptation${selectedTraits.length===1?'':'s'}.`)
124: }
125: function breedDialog() {
126:   if(game.creatures.length<2)return toast('You need two creatures to breed.')
127:   const a=selected(), others=game.creatures.filter(c=>c.id!==a.id)
128:   showModal(`<button class="modal-close" data-action="close">×</button><div class="eyebrow">INHERITANCE LAB · GEN 0${(a.generation||0)+1}</div><h2>Pair a lineage</h2><p>Choose a second parent. Their expressed traits combine with ${esc(a.name)}'s DNA; mutation can create new adaptations.</p><div class="parent-preview"><div class="parent-chip"><i style="--creature-color:${phenotype(a.genome).bodyColor}"></i><span><b>${esc(a.name)}</b><small>SELECTED PARENT</small></span></div><span class="cross">×</span><select id="mate-select">${others.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${c.sex==='F'?'♀':'♂'} · GEN ${c.generation||0}</option>`).join('')}</select></div><div class="modal-actions"><button class="secondary-btn" data-action="close">CANCEL</button><button class="primary-btn" data-action="breed-confirm">CREATE OFFSPRING ↗</button></div>`)
129: }
130: function breed() {
131:   const parent=selected(), mate=game.creatures.find(c=>c.id===$('#mate-select')?.value)
132:   if(!mate)return closeModal()
133:   const {genome,mutations}=breedGenomes(parent.genome,mate.genome)
134:   const child={id:cryptoId(),name:makeName(genome,[parent,mate]),genome,sex:sexOf(),needs:freshNeeds(90),wins:0,battles:0,born:Date.now(),generation:Math.max(parent.generation||0,mate.generation||0)+1,parents:[parent.id,mate.id]}
135:   game.creatures.push(child); game.selected=child.id; closeModal(); if(mode==='habitat') { world.addCreature(child,{position:[0,0,0]}); world.setSelected(child.id) }
136:   persist(); renderRoster(); renderProfile(); toast(`${child.name} hatched with ${mutations.length} mutated gene${mutations.length===1?'':'s'}!`)
137: }
138: function renameDialog() {
139:   const c=selected(); showModal(`<button class="modal-close" data-action="close">×</button><div class="eyebrow">CREATURE DOSSIER</div><h2>Rename specimen</h2><label class="field-label">SPECIMEN NAME<input id="rename-input" maxlength="20" value="${esc(c.name)}"></label><div class="modal-actions"><button class="secondary-btn" data-action="close">CANCEL</button><button class="primary-btn" data-action="rename-confirm">SAVE NAME</button></div>`)
140:   $('#rename-input').focus(); $('#rename-input').select()
141: }
142: function rename() { const input=$('#rename-input'), name=input?.value.trim(); if(!name)return toast('A name cannot be empty.'); selected().name=name; closeModal(); renderRoster(); renderProfile(); persist(); toast('Specimen renamed.') }
143: function arenaDialog() {
144:   if(game.creatures.length<2)return toast('Discover another creature before entering the arena.')
145:   const player=selected(), foes=game.creatures.filter(c=>c.id!==player.id)
