156: function updateModeUI() {
157:   document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode))
158:   $('#stage-title').textContent=mode==='arena'?'The Crucible':'The Verdant Hollow'
159:   $('#stage-kicker').textContent=mode==='arena'?'⚔ COMBAT ARENA':'◌ OPEN HABITAT'
160:   $('#scene-tag-text').textContent=mode==='arena'?'BATTLE IN PROGRESS':'ECOSYSTEM ACTIVE'
